232	
233	    /**
234	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
235	     * the canonical form each stored value must take: the address is trimmed,
236	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
237	     * telephone is converted to E.164, any email is lower-cased and a missing
238	     * registration date defaults to today. Field-level rejections are reported here
239	     * rather than inline in {@link #addOwner}, and normalisation runs before any
240	     * household comparison so those comparisons see the canonical values.
241	     *
242	     * @param owner the freshly-mapped owner to normalise
243	     * @return {@code true} if the fields are valid, or {@code false} if the address
244	     *         is blank after normalisation, the telephone cannot form a valid
245	     *         E.164 number, or a supplied registration date is later than the
246	     *         server date, in which case the request must be rejected with
247	     *         {@code 400 Bad Request}
248	     */
249	    private boolean normalizeNewOwner(Owner owner) {
250	        if (!normalizeAddressFields(owner)) {
251	            return false;
252	        }
253	        String telephone = Telephones.toE164(owner.getTelephone());
254	        if (telephone == null) {
255	            return false;
256	        }
257	        owner.setTelephone(telephone);
258	        if (owner.getEmail() != null) {
259	            String email = owner.getEmail().toLowerCase();
260	            owner.setEmail(email);
261	            if (emailDomainIsBlocked(email)) {
262	                return false;
263	            }
264	        }
265	        if (!owner.postcodeValidForLocality()) {
266	            return false;
267	        }
268	        if (owner.getRegistrationDate() == null) {
269	            owner.setRegistrationDate(LocalDate.now());
270	        } else if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
271	            return false;
272	        }
273	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
274	        return true;
275	    }
276	
277	    /**
278	     * Normalise the owner's address fields in place to their canonical stored form
279	     * (trimmed, whitespace-collapsed, upper-cased and with common abbreviations
280	     * expanded; see {@link Owner#normalizeAddress(String)}), gathering the whole address
281	     * concern of {@link #normalizeNewOwner} in one place. The structured form is
282	     * preferred: when a non-blank {@code addressLine1} is supplied it (and any
283	     * {@code addressLine2}) is normalised, and the flat {@code address} is composed from
284	     * them — the normalised {@code addressLine1}, with a single space and the normalised
285	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the
286	     * flat {@code address} is normalised on its own, preserving backward compatibility.
287	     * Either way the canonicalised values are written back so every later household
288	     * comparison and read sees them.
289	     *
290	     * @param owner the freshly-mapped owner whose address fields are being normalised
291	     * @return {@code true} once an address is valid and stored, or {@code false} when
292	     *         neither a structured {@code addressLine1} nor a flat {@code address} is
293	     *         present after normalisation, in which case the request must be rejected
294	     *         with {@code 400 Bad Request}
295	     */
296	    private boolean normalizeAddressFields(Owner owner) {
297	        String addressLine1 = Owner.normalizeAddress(owner.getAddressLine1());
298	        if (!addressLine1.isEmpty()) {
299	            owner.setAddressLine1(addressLine1);
300	            String composed = addressLine1;
301	            String addressLine2 = Owner.normalizeAddress(owner.getAddressLine2());
302	            if (!addressLine2.isEmpty()) {
303	                owner.setAddressLine2(addressLine2);
304	                composed = addressLine1 + " " + addressLine2;
305	            }
306	            owner.setAddress(composed);
307	            return true;
308	        }
309	        String address = Owner.normalizeAddress(owner.getAddress());
310	        if (address.isEmpty()) {
311	            return false;
312	        }
313	        owner.setAddress(address);
314	        return true;
315	    }
316	
317	    /**
318	     * Email domains that identify disposable, throw-away mailboxes. An owner whose
319	     * email address is on one of these domains is rejected with {@code 400 Bad
320	     * Request} rather than created.
321	     */
322	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
323	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
324	
325	    /**
326	     * Whether the given (already lower-cased) email address belongs to a disposable
327	     * mailbox domain on the blocklist. The domain is the part after the final
328	     * {@code '@'}; an address without one is treated as having no blocked domain.
329	     *
330	     * @param email the owner's normalised (lower-cased) email address
331	     * @return {@code true} if the email's domain is on the disposable-domain blocklist
332	     */
333	    private static boolean emailDomainIsBlocked(String email) {
334	        int at = email.lastIndexOf('@');
335	        if (at < 0) {
336	            return false;
337	        }
338	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
339	    }
340	
341	    /**
342	     * Roll the given date forward to the next business day when it falls on a
343	     * weekend: a Saturday or Sunday is advanced to the following Monday, while a
344	     * weekday is returned unchanged. Applied to the effective registration date
345	     * (whether supplied in the request or defaulted to the server date) so that
346	     * every value derived from it uses the adjusted business day.
347	     *
348	     * @param date the effective registration date
349	     * @return the same date if it is a weekday, otherwise the next Monday
350	     */
351	    private static LocalDate rollToBusinessDay(LocalDate date) {
352	        switch (date.getDayOfWeek()) {
353	            case SATURDAY:
354	                return date.plusDays(2);
355	            case SUNDAY:
356	                return date.plusDays(1);
357	            default:
358	                return date;
359	        }
360	    }
361	
362	    /**
363	     * Find an existing owner that belongs to the same household as the given owner,
364	     * i.e. shares the same last name (compared case-insensitively with runs of
365	     * whitespace collapsed to a single space) and postcode, and so resolves to the same
366	     * deterministic {@code householdId}.
367	     *
368	     * @param owner the candidate owner being created
369	     * @return the matching existing owner, or empty if none exists
370	     */
371	    private Optional<Owner> findHouseholdMember(Owner owner) {
372	        return this.clinicService.findAllOwners().stream()
373	            .filter(existing -> existing.sameHouseholdAs(owner))
374	            .findFirst();
375	    }
376	
377	    /**
378	     * Assign the owner's computed-at-creation attributes in place: its customer code,
379	     * namesake count, membership number, bulk-signup warning and household size. Unlike
380	     * the {@code @Transient} attributes {@link Owner} recomputes on demand, these are
381	     * derived once here — from the owner's own (already normalised) fields and from the
382	     * wider owner population — and persisted with the owner. Run after normalisation,
383	     * household resolution and the identity-key check, so every value reflects the
384	     * owner's final field values and any household it has joined, and immediately before
385	     * the owner is saved.
386	     *
387	     * <p>Ordering matters: the customer code is assigned first because the membership
388	     * number is built from it.
389	     *
390	     * @param owner the candidate owner being created, after household resolution
391	     * @param declaredHouseholdMember whether this owner was created as a declared member
392	     *                                of an existing household (it shared an existing
393	     *                                owner's household and set {@code sharesHousehold}),
394	     *                                in which case it is not a suspected duplicate
395	     */
396	    private void assignDerivedAttributes(Owner owner, boolean declaredHouseholdMember) {
397	        owner.setCustomerCode(deduplicatedCustomerCode(owner));
398	        owner.setNamesakeCount(countNamesakes(owner));
399	        owner.setMembershipNumber(membershipNumber(owner));
400	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
401	        owner.setHouseholdSize(householdSize(owner));
402	        assignPossibleDuplicate(owner, declaredHouseholdMember);
403	    }
404	
405	    /**
406	     * Compute the customer code to assign to the candidate owner, de-duplicated against
407	     * every existing owner's customer code. The base code is the owner's computed
408	     * {@code <REGION>-<HASH8>} (see {@link Owner#computeCustomerCode()}); when it does not
409	     * already belong to an existing owner it is used unchanged. Otherwise it collides, and
410	     * {@code -<n>} is appended with the smallest integer {@code n} of 2 or more that yields
411	     * a code no existing owner holds, so the returned customer code is unique. Evaluated
412	     * before the owner is saved, so only pre-existing owners are considered.
413	     *
414	     * @param owner the candidate owner being created, after normalisation
415	     * @return the unique (de-duplicated) customer code to assign
416	     */
417	    private String deduplicatedCustomerCode(Owner owner) {
418	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
419	            .map(Owner::getCustomerCode)
420	            .filter(code -> code != null)
421	            .collect(java.util.stream.Collectors.toSet());
422	        String base = owner.computeCustomerCode();
423	        if (!existingCodes.contains(base)) {
424	            return base;
425	        }
426	        int n = 2;
427	        while (existingCodes.contains(base + "-" + n)) {
428	            n++;
429	        }
430	        return base + "-" + n;
431	    }
432	
433	    /**
434	     * Flag the candidate owner as a possible duplicate of an existing owner. A soft
435	     * match is an existing owner that shares this owner's last name (compared
436	     * case-insensitively) and postcode but carries a different (normalised) telephone.
437	     * When such a match exists the owner is still created, but with
438	     * {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to the matching
439	     * owner's id; otherwise {@code possibleDuplicate} is false and no match id is
440	     * recorded. The earliest-created matching owner (lowest id) is chosen so the result
441	     * is deterministic. Evaluated before the owner is saved, so only pre-existing owners
442	     * are considered.
443	     *
444	     * <p>A declared household member — one that shared an existing owner's household
445	     * (same last name and postcode) and was admitted because it set
446	     * {@code sharesHousehold} — is never flagged: a declared member is not a suspected
447	     * duplicate, so its {@code possibleDuplicate} is false with no match id.
448	     *
449	     * @param owner the candidate owner being created, after household resolution
450	     * @param declaredHouseholdMember whether the owner is a declared household member
451	     */
452	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
453	        if (declaredHouseholdMember) {
454	            owner.setPossibleDuplicate(false);
455	            owner.setPossibleDuplicateOf(null);
456	            return;
457	        }
458	        String lastName = normalizeName(owner.getLastName());
459	        String postcode = owner.getPostcode();
460	        String telephone = owner.getTelephone();
461	        Optional<Owner> match = this.clinicService.findAllOwners().stream()
462	            .filter(existing -> postcode != null && postcode.equals(existing.getPostcode())
463	                && normalizeName(existing.getLastName()).equals(lastName)
464	                && telephone != null && !telephone.equals(existing.getTelephone()))
465	            .min(Comparator.comparing(Owner::getId));
466	        if (match.isPresent()) {
467	            owner.setPossibleDuplicate(true);
468	            owner.setPossibleDuplicateOf(match.get().getId());
469	        } else {
470	            owner.setPossibleDuplicate(false);
471	            owner.setPossibleDuplicateOf(null);
472	        }
473	    }
474	
475	    /**
476	     * Count how many owners belong to the given owner's household once this create
477	     * completes: the owners that already share its deterministic {@code householdId}
478	     * (derived from last name and postcode) plus the owner being created. Evaluated
479	     * after the owner's {@code householdId} has been assigned. An owner whose
480	     * {@code householdId} matches no existing owner is a household of one.
481	     *
482	     * @param owner the candidate owner being created, after household resolution
483	     * @return the household member count after this create (at least {@code 1})
484	     */
485	    private int householdSize(Owner owner) {
486	        String householdId = owner.getHouseholdId();
487	        if (householdId == null) {
488	            return 1;
489	        }
490	        long existing = this.clinicService.findAllOwners().stream()
491	            .filter(other -> householdId.equals(other.getHouseholdId()))
492	            .count();
493	        return (int) existing + 1;
494	    }
495	
496	    /**
497	     * Count the existing owners that share the given owner's first and last name,
498	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
499	     * before the new owner is saved, so the result reflects only owners that
500	     * already existed at creation time.
501	     *
502	     * @param owner the candidate owner being created
503	     * @return the number of existing namesakes
504	     */
505	    private int countNamesakes(Owner owner) {
506	        String firstName = normalizeName(owner.getFirstName());
507	        String lastName = normalizeName(owner.getLastName());
508	        return (int) this.clinicService.findAllOwners().stream()
509	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
510	                && normalizeName(existing.getLastName()).equals(lastName))
511	            .count();
512	    }
513	
514	    private static String normalizeName(String value) {
515	        return value == null ? "" : value.trim().toLowerCase();
516	    }
517	
518	    /**
519	     * Determine whether the given city has already reached its owner capacity, i.e.
520	     * it already contains 50 or more existing owners (compared case-insensitively
521	     * with surrounding whitespace trimmed). A new owner may not be created in a city
522	     * that is at capacity.
523	     *
524	     * @param city the candidate owner's city
525	     * @return {@code true} if the city already holds 50 or more owners
526	     */
527	    private boolean cityIsAtCapacity(String city) {
528	        String normalizedCity = normalizeName(city);
529	        long count = this.clinicService.findAllOwners().stream()
530	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
531	            .count();
532	        return count >= 50;
533	    }
534	
535	    /**
536	     * Determine whether the daily owner-creation limit has already been reached, i.e.
537	     * 100 or more owners already carry the given registration date. A new owner may
538	     * not be created once that day's cap is reached.
539	     *
540	     * @param registrationDate the registration date the new owner would be created with
541	     * @return {@code true} if 100 or more existing owners share that registration date
542	     */
543	    private boolean dailyLimitReached(LocalDate registrationDate) {
544	        long count = this.clinicService.findAllOwners().stream()
545	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
546	            .count();
547	        return count >= 100;
548	    }
549	
550	    /**
551	     * Determine whether more than 80 owners have already been created for the given
552	     * registration date, i.e. strictly more than 80 existing owners carry that date.
553	     * Evaluated before the new owner is saved, so it reflects only owners that
554	     * already existed at creation time.
555	     *
556	     * @param registrationDate the registration date the new owner would be created with
557	     * @return {@code true} if more than 80 existing owners share that registration date
558	     */
559	    private boolean bulkSignupWarning(LocalDate registrationDate) {
560	        long count = this.clinicService.findAllOwners().stream()
561	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
562	            .count();
563	        return count > 80;
564	    }
565	
566	    /**
567	     * Write the create audit record for a freshly-saved owner. Keeps the audit format in
568	     * one place so it stays in step with the owner's identity: it reports the assigned
569	     * customer code alongside the owner's id, registration date, membership level and
570	     * membership number.
571	     *
572	     * @param owner the owner that has just been created and saved
573	     */
574	    private void auditOwnerCreated(Owner owner) {
575	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
576	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
577	            owner.getMembershipNumber());
578	    }
579	
580	    /**
581	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
582	     * where {@code <customerCode>} is the owner's already-assigned customer code and
583	     * YY is the last two digits of the registration date's year (e.g.
584	     * {@code NSW-9F86D081-M26}). Evaluated after the customer code and registration date
585	     * have been set.
586	     *
587	     * @param owner the owner being created, with customer code and registration date
588	     *              already assigned
589	     * @return the assigned membership number
590	     */
591	    private String membershipNumber(Owner owner) {
592	        int yy = owner.getRegistrationDate().getYear() % 100;
593	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
594	    }
595	}
